function PVPArenaAgainstHeadGroupNode:RefreshUI(info, playerId, isShowTicketNum, isLoser, isQuizzed)
    local isPlayerSelf = playerId == self.selfPlayerId
    self.playerId = playerId
    self.isPlayerSelf = isPlayerSelf

    local excludeDialogs = {}
    PVPArenaUtils.RefreshPlayerHeadNode(self.PlayerHeadNode.gameObject, playerId, info, excludeDialogs, Bind(self, self.OnClickHeadAction))

    isLoser = checkBool(isLoser)
    KTool.SetActive(self.Black.gameObject,     isLoser)
    KTool.SetActive(self.NameBlack.gameObject, isLoser)
    KTool.SetActive(self.PlayerIco.gameObject, isPlayerSelf or isQuizzed)
    self.TxtPlayer.text = info.name
    self.LevelText.text = info.level

    local playerIcoName
    if isPlayerSelf then
        playerIcoName = "pvp_map_ico_player"
    elseif isQuizzed then
        playerIcoName = "pvp_map_ico_vote"
    end

    if playerIcoName then
        self.PlayerIco:LoadSprite(string.format(BasePath, playerIcoName))
    end

    if self.ImgTicket then
        KTool.SetActive(self.ImgTicket.gameObject, isShowTicketNum)
        if isShowTicketNum then
            self.TicketText.text = info.quizzedNum
        end
    end
end
