function PVPArenaAgainstHeadGroupNode:OnClickHeadAction()
    local excludeDialogs = {
        {id = Constants.UITypeIds.PVPArenaAgainstDialog}
    }
    --- 按钮不会进入比赛信息
    --PVPArenaUtils.ShowDialogByMatchChartState(self.state, self.oneMatchChartData, self.playerId, excludeDialogs)
    ---@type PVPArenaComponent
    local pvpArenaComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PVPArenaComponent)
    local isPlayerSelf      = self.isPlayerSelf
    local battleStatus      = checkNumber(pvpArenaComponent:GetPVPArenaEntryDojo().battleStatus)
    local mainPanelStatus   = pvpArenaComponent:GetMainPanelStatus()
    local state             = PVPArenaUtils.InitMatchChartClickState(self.isAudience, isPlayerSelf, battleStatus, mainPanelStatus)

    PVPArenaUtils.ShowDialogByMatchChartState(state, self.oneMatchChartData, self.playerId, excludeDialogs)
end

